sealed class Resultado
class Exito(val valor: Int): Resultado()
class Fracaso(val error: String): Resultado()

fun procesar(r: Resultado): String = when (r) {
    is Exito -> "OK: ${r.valor}"
    is Fracaso -> "ERROR: ${r.error}"
}
println(procesar(Exito(42)))
